def deletions(s, c):
    lo, hi, d = 0, len(s) - 1, 0
    while lo < hi:
        if s[lo] == s[hi]:
            lo, hi = lo + 1, hi - 1
        elif s[lo] == c:
            lo, d = lo + 1, d + 1
        elif s[hi] == c:
            hi, d = hi - 1, d + 1
        else:
            return -1
    return d


def fewest_deletions(s):
    lo, hi = 0, len(s) - 1
    while lo < hi and s[lo] == s[hi]:
        lo, hi = lo + 1, hi - 1
    if lo >= hi:
        return 0
    a, b = deletions(s, s[lo]), deletions(s, s[hi])
    if a < 0 or b < 0:
        return max(a, b)
    return min(a, b)

