static int deletions(String s, char c) {
    int lo = 0, hi = s.length() - 1, d = 0;
    while (lo < hi) {
        if (s.charAt(lo) == s.charAt(hi)) {
            lo++;
            hi--;
        } else if (s.charAt(lo) == c) {
            lo++;
            d++;
        } else if (s.charAt(hi) == c) {
            hi--;
            d++;
        } else {
            return -1;
        }
    }
    return d;
}

static int fewestDeletions(String s) {
