    while (lo < hi && s.charAt(lo) == s.charAt(hi)) {
        lo++;
        hi--;
    }
    if (lo >= hi) return 0;
    int a = deletions(s, s.charAt(lo)), b = deletions(s, s.charAt(hi));
    if (a < 0 || b < 0) return Math.max(a, b);
    return Math.min(a, b);
