int fewestDeletions(const char* s) {
    int n = strlen(s), lo = 0, hi = n - 1;
    while (lo < hi && s[lo] == s[hi]) {
        lo++;
        hi--;
    }
    if (lo >= hi) return 0;
    int a = deletions(s, n, s[lo]), b = deletions(s, n, s[hi]);
    if (a < 0 || b < 0) return a > b ? a : b;
    return a < b ? a : b;
}

